import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.8tqBsFWt.js";const p=JSON.parse('{"title":"Team availability for the next two weeks","description":"","frontmatter":{},"headers":[],"relativePath":"playbook/team-availability.md","filePath":"playbook/team-availability.md"}'),n={name:"playbook/team-availability.md"};function r(l,e,s,h,c,d){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="team-availability-for-the-next-two-weeks" tabindex="-1">Team availability for the next two weeks <a class="header-anchor" href="#team-availability-for-the-next-two-weeks" aria-label="Permalink to &quot;Team availability for the next two weeks&quot;">​</a></h1><p><strong>Cadence</strong>: Weekly, or ad hoc · <strong>Who</strong>: Managers and Owners</p><h2 id="situation" tabindex="-1">Situation <a class="header-anchor" href="#situation" aria-label="Permalink to &quot;Situation&quot;">​</a></h2><p>A prospect asks if you can start a new project next month. A PM needs to pull someone onto an urgent piece. You need to know who has real capacity — not who looks free on a calendar, but who has unallocated hours after accounting for their current commitments and any time off.</p><h2 id="in-the-console" tabindex="-1">In the console <a class="header-anchor" href="#in-the-console" aria-label="Permalink to &quot;In the console&quot;">​</a></h2><p>Open <strong>Capacity</strong> (<code>/console/capacity</code>). The heatmap is one row per person, one column per week — each cell is committed vs available hours for that week, colour-banded so over-commitment is obvious at a glance. Prev/Next slide the window; click a person for their per-project burn.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>A table, one row per person:</p><p>| Name | Discipline | Committed hours | Available hours | Remaining | OOO in window |</p><ul><li><strong>Committed hours</strong> is the prorated share of their current allocations that falls in the two-week window, not the lifetime total. This is the important bit — envelopes are project-lifetime, but this play tells you what lands in <em>this window</em>.</li><li><strong>Available hours</strong> is the window capacity net of time off already approved</li><li><strong>Remaining</strong> = Available − Committed. A negative number means over-committed.</li></ul><p>Sorted: most remaining capacity first.</p><p>Any person whose commitments include envelopes without a project deadline is flagged — their window share is an estimate based on a 12-week rolling horizon.</p><h2 id="who-can-run-it" tabindex="-1">Who can run it <a class="header-anchor" href="#who-can-run-it" aria-label="Permalink to &quot;Who can run it&quot;">​</a></h2><p>Managers and Owners. Availability is hours only — no cost or billing figures — so both Managers and Owners see the whole team&#39;s capacity.</p><h2 id="related-plays" tabindex="-1">Related plays <a class="header-anchor" href="#related-plays" aria-label="Permalink to &quot;Related plays&quot;">​</a></h2><ul><li><a href="./ooo-coordination.html">OOO coordination for the week ahead</a> — shorter window, time-off focus</li><li><a href="./project-health-probe.html">Project health probe</a> — before you commit someone to another engagement</li></ul>',16)])])}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
